from pathlib import Path
from datetime import datetime
import argparse
import csv
import yaml

import matplotlib
matplotlib.use("Agg")  # headless backend (saves to file)
import matplotlib.pyplot as plt

from ultralytics import YOLO

# ============================================================
# SETTINGS
# ============================================================

# Path to the YOLO dataset (generated by prepare_yolo_dataset.py)
DATA_YAML = Path(
    "dataset_yolo/data.yaml"
)

# Folder where training results will be saved
PROJECT_DIR = Path(
    "runs_curva_embedding"
)

# Folder where embedding_ranking.py saved the pair CSVs
EMBEDDING_RUNS_DIR = Path(
    "runs_embedding"
)

# Same models as train_compare.py (small variant).
MODELS = {
    "yolov8s": "yolov8s.pt",
    "yolo11s": "yolo11s.pt",
    "yolo26s": "yolo26s.pt",
}

# ------------------------------------------------------------
# BASIC TRAINING PARAMETERS
# (same as train_compare.py, for a fair comparison)
# ------------------------------------------------------------

EPOCHS = 300
IMG_SIZE = 640
BATCH = 16
PATIENCE = 20          # early stopping
SEED = 42
DEVICE = 0             # 0 = first GPU | "cpu" = no GPU

# ------------------------------------------------------------
# LEARNING CURVE
# ------------------------------------------------------------

# Step of the training image increment (10 at a time).
STEP = 10

METRICS = ["mAP50", "mAP50-95", "precision", "recall"]


# ============================================================
# DIVERSITY-BASED SELECTION (from the embedding ranking)
# ============================================================

def find_embedding_csv(csv_arg):
    """
    Locates the embedding pairs CSV

    If the user passes --embedding-csv, uses that path.
    Otherwise, takes the most recent embedding_pares.csv in runs_embedding/embedding_*/
    """

    if csv_arg:
        path = Path(csv_arg)
        if not path.exists():
            raise FileNotFoundError(
                f"Embedding CSV not found: {path}"
            )
        return path

    candidates = sorted(
        EMBEDDING_RUNS_DIR.glob("embedding_*/embedding_pares.csv"),
        key=lambda p: p.stat().st_mtime,
    )

    if not candidates:
        raise FileNotFoundError(
            "No embedding_pares.csv found in "
            f"{EMBEDDING_RUNS_DIR}/embedding_*/. "
            "Run embedding_ranking.py first or pass "
            "--embedding-csv."
        )

    return candidates[-1]  # most recent


def load_embedding_pairs(csv_path):
    """
    Reads the pairs from the CSV and returns the list ordered
    from the LEAST similar to the MOST similar (lowest cosine first)
    """

    pairs = []

    with open(csv_path, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            pairs.append(
                {
                    "image_a": row["image_a"],
                    "image_b": row["image_b"],
                    "cosine": float(row["cosine"]),
                }
            )

    # Least similar first (prioritizes diversity)
    pairs.sort(key=lambda p: p["cosine"])

    return pairs


def order_images_by_diversity(pairs):
    """
    Walks through the pairs from least to most similar and adds
    the TWO images of each pair to the selection order

    Same mechanics as ssim_learning_curve.py (only the metric changes)
    """

    order = []
    seen = set()

    for pair in pairs:
        a = pair["image_a"]
        b = pair["image_b"]

        # The pair only counts if BOTH images are new
        if a in seen or b in seen:
            continue

        order.append(a)
        order.append(b)
        seen.add(a)
        seen.add(b)

    return order


def complete_order(order, train_images):
    """
    Ensures all training images appear in the order
    """

    present = set(order)

    missing = sorted(
        name
        for name in train_images
        if name not in present
    )

    return order + missing


# ============================================================
# TRAINING SUBSETS PREPARATION
# ============================================================

def load_dataset_config():
    """Reads data.yaml and resolves the training images directory."""

    with open(DATA_YAML, "r", encoding="utf-8") as f:
        cfg = yaml.safe_load(f)

    base = Path(cfg["path"])
    train_dir = base / cfg["train"]

    return cfg, base, train_dir


def map_train_images(train_dir):
    """Maps file name -> full path (training split)."""

    extensions = {
        ".jpg", ".jpeg", ".png",
        ".bmp", ".tif", ".tiff",
    }

    mapping = {
        img.name: img
        for img in train_dir.iterdir()
        if img.is_file()
        and img.suffix.lower() in extensions
    }

    if not mapping:
        raise FileNotFoundError(
            f"No training image found in: {train_dir}"
        )

    return mapping


def generate_sizes(total):
    """10, 20, 30, ... up to and including the total (100% of data)."""

    sizes = list(range(STEP, total + 1, STEP))

    if not sizes or sizes[-1] != total:
        sizes.append(total)

    return sizes


def create_subset_data_yaml(cfg, subset_paths, out_dir, n):
    """
    Creates a temporary data.yaml whose 'train' points to a .txt
    with the image subset. 'val' and 'test' stay fixed
    """

    list_txt = out_dir / f"train_{n}.txt"

    with open(list_txt, "w", encoding="utf-8") as f:
        for img in subset_paths:
            f.write(f"{img.resolve()}\n")

    new_cfg = dict(cfg)
    new_cfg["train"] = str(list_txt.resolve())

    yaml_path = out_dir / f"data_{n}.yaml"

    with open(yaml_path, "w", encoding="utf-8") as f:
        yaml.safe_dump(
            new_cfg,
            f,
            sort_keys=False,
            allow_unicode=True,
        )

    return yaml_path


# ============================================================
# TRAINING + VALIDATION (one curve step)
# ============================================================

def train(name, weights, data_yaml, n, out_dir):

    print("\n" + "=" * 60)
    print(f"TRAINING: {name}  |  {n} training images")
    print("=" * 60)

    run_name = f"{name}_n{n}"

    model = YOLO(weights)

    model.train(
        data=str(data_yaml),
        epochs=EPOCHS,
        imgsz=IMG_SIZE,
        batch=BATCH,
        patience=PATIENCE,
        seed=SEED,
        device=DEVICE,
        project=str(out_dir),
        name=run_name,
        exist_ok=True,
    )

    # Evaluation on the test set (FIXED for all)
    metrics = model.val(
        data=str(data_yaml),
        split="test",
        imgsz=IMG_SIZE,
        batch=BATCH,
        device=DEVICE,
        project=str(out_dir),
        name=f"{run_name}_test",
        exist_ok=True,
    )

    return {
        "model": name,
        "n_images": n,
        "mAP50": round(float(metrics.box.map50), 4),
        "mAP50-95": round(float(metrics.box.map), 4),
        "precision": round(float(metrics.box.mp), 4),
        "recall": round(float(metrics.box.mr), 4),
    }


# ============================================================
# TABLES (CSV + MARKDOWN)
# ============================================================

def save_csv(results, csv_path):

    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(
            f,
            fieldnames=["model", "n_images"] + METRICS,
        )
        writer.writeheader()
        writer.writerows(results)


def save_markdown(results, md_path):

    lines = []
    lines.append(
        "# Diversity-based Learning Curve (DINOv2 embeddings) - test"
    )
    lines.append("")
    lines.append(
        "Images added by least similar pairs "
        "(cosine of DINOv2 embeddings), cumulative increment "
        "of 10 at a time."
    )
    lines.append("")
    lines.append(
        "| Model | # images | " + " | ".join(METRICS) + " |"
    )
    lines.append(
        "|" + "---|" * (len(METRICS) + 2)
    )

    for r in results:
        values = " | ".join(
            f"{r[m]:.4f}" for m in METRICS
        )
        lines.append(
            f"| {r['model']} | {r['n_images']} | {values} |"
        )

    md_path.write_text("\n".join(lines) + "\n", encoding="utf-8")


# ============================================================
# LEARNING CURVE CHART
# ============================================================

def generate_learning_curve(results, out_dir):
    """
    One figure with 4 subplots (one per metric)

    In each subplot: X axis = number of training images, Y axis = metric, one line per model
    """

    colors = {
        name: color
        for name, color in zip(
            MODELS.keys(),
            ["#4C72B0", "#DD8452", "#55A868"],
        )
    }

    fig, axes = plt.subplots(2, 2, figsize=(13, 9))
    axes = axes.flatten()

    for idx, metric in enumerate(METRICS):

        ax = axes[idx]

        for name in MODELS:

            points = sorted(
                (r for r in results if r["model"] == name),
                key=lambda r: r["n_images"],
            )

            xs = [p["n_images"] for p in points]
            ys = [p[metric] for p in points]

            ax.plot(
                xs,
                ys,
                marker="o",
                label=name,
                color=colors[name],
            )

        ax.set_title(metric, fontsize=13, fontweight="bold")
        ax.set_xlabel("Number of training images")
        ax.set_ylabel(metric)
        ax.set_ylim(0, 1)
        ax.grid(linestyle="--", alpha=0.4)
        ax.legend(title="Model", fontsize=9)

    fig.suptitle(
        "Learning curve (diversity-based selection - DINOv2 embeddings)",
        fontsize=15,
        fontweight="bold",
    )
    fig.tight_layout(rect=(0, 0, 1, 0.97))

    path_curve = out_dir / "curva_aprendizado_embedding.png"
    fig.savefig(path_curve, dpi=150)
    plt.close(fig)

    return path_curve


# ============================================================
# FINAL POINT BAR CHART (100% of data)
# ============================================================

def generate_final_bars(results, out_dir):
    """Bars comparing the models at the largest size (100%)."""

    n_max = max(r["n_images"] for r in results)
    finals = [r for r in results if r["n_images"] == n_max]
    finals = sorted(
        finals,
        key=lambda r: list(MODELS).index(r["model"]),
    )

    models = [r["model"] for r in finals]
    colors = ["#4C72B0", "#DD8452", "#55A868"]

    fig, axes = plt.subplots(2, 2, figsize=(12, 9))
    axes = axes.flatten()

    for idx, metric in enumerate(METRICS):

        ax = axes[idx]
        values = [r[metric] for r in finals]

        bars = ax.bar(
            models,
            values,
            color=colors[: len(models)],
        )

        ax.set_title(metric, fontsize=13, fontweight="bold")
        ax.set_ylim(0, 1)
        ax.grid(axis="y", linestyle="--", alpha=0.4)

        for bar, value in zip(bars, values):
            ax.text(
                bar.get_x() + bar.get_width() / 2,
                value + 0.01,
                f"{value:.3f}",
                ha="center",
                va="bottom",
                fontsize=10,
            )

    fig.suptitle(
        f"Comparison on the full set ({n_max} images) - test",
        fontsize=15,
        fontweight="bold",
    )
    fig.tight_layout(rect=(0, 0, 1, 0.97))

    path_bars = out_dir / "comparacao_final.png"
    fig.savefig(path_bars, dpi=150)
    plt.close(fig)

    return path_bars


# ============================================================
# EXECUTION
# ============================================================

def main():

    parser = argparse.ArgumentParser(
        description=(
            "Learning curve with image selection by diversity "
            "(least similar pairs via cosine of DINOv2 "
            "embeddings)."
        )
    )
    parser.add_argument(
        "--embedding-csv",
        default=None,
        help=(
            "Path to embedding_pares.csv. If omitted, uses the "
            "most recent one in runs_embedding/embedding_*/."
        ),
    )
    args = parser.parse_args()

    if not DATA_YAML.exists():
        raise FileNotFoundError(
            f"data.yaml not found: {DATA_YAML}\n"
            "Run prepare_yolo_dataset.py first."
        )

    PROJECT_DIR.mkdir(parents=True, exist_ok=True)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    out_dir = PROJECT_DIR / f"curva_embedding_{timestamp}"
    out_dir.mkdir(parents=True, exist_ok=True)

    subsets_dir = out_dir / "subsets"
    subsets_dir.mkdir(parents=True, exist_ok=True)

    # --------------------------------------------------------
    # Build the selection order from the embedding ranking
    # --------------------------------------------------------

    embedding_csv = find_embedding_csv(args.embedding_csv)
    pairs = load_embedding_pairs(embedding_csv)

    cfg, base, train_dir = load_dataset_config()
    image_map = map_train_images(train_dir)

    order_names = order_images_by_diversity(pairs)
    order_names = complete_order(order_names, image_map.keys())

    # Keep only names that exist in the training split, preserving order
    order_names = [
        name for name in order_names if name in image_map
    ]

    order_paths = [image_map[name] for name in order_names]

    total = len(order_paths)
    sizes = generate_sizes(total)

    print("\n" + "=" * 60)
    print("DIVERSITY-BASED LEARNING CURVE (DINOv2 embeddings)")
    print("=" * 60)
    print(f"Embedding pairs CSV:   {embedding_csv}")
    print(f"Total training images: {total}")
    print(f"Sizes evaluated:       {sizes}")
    print(f"Models:                {list(MODELS)}")
    print(f"Evaluation (fixed) on: test")

    # --------------------------------------------------------
    # Create the data.yaml for each size (cumulative increment)
    # --------------------------------------------------------

    data_yaml_per_size = {}

    for n in sizes:
        subset = order_paths[:n]  # cumulative
        data_yaml_per_size[n] = create_subset_data_yaml(
            cfg, subset, subsets_dir, n
        )

    # --------------------------------------------------------
    # Train each model at each size
    # --------------------------------------------------------

    results = []

    for name, weights in MODELS.items():
        for n in sizes:
            result = train(
                name,
                weights,
                data_yaml_per_size[n],
                n,
                out_dir,
            )
            results.append(result)

    # --------------------------------------------------------
    # TERMINAL TABLE
    # --------------------------------------------------------

    print("\n" + "=" * 60)
    print("RESULTS (test set)")
    print("=" * 60)

    header = (
        f"{'Model':<12}"
        f"{'Nimg':>6}"
        f"{'mAP50':>10}"
        f"{'mAP50-95':>12}"
        f"{'Precision':>12}"
        f"{'Recall':>10}"
    )

    print(header)
    print("-" * 62)

    for r in results:
        print(
            f"{r['model']:<12}"
            f"{r['n_images']:>6}"
            f"{r['mAP50']:>10}"
            f"{r['mAP50-95']:>12}"
            f"{r['precision']:>12}"
            f"{r['recall']:>10}"
        )

    # --------------------------------------------------------
    # SAVE TABLES AND CHARTS
    # --------------------------------------------------------

    csv_path = out_dir / "metricas.csv"
    md_path = out_dir / "metricas.md"

    save_csv(results, csv_path)
    save_markdown(results, md_path)

    path_curve = generate_learning_curve(results, out_dir)
    path_bars = generate_final_bars(results, out_dir)

    print("\n" + "=" * 60)
    print("GENERATED FILES")
    print("=" * 60)
    print(f"CSV table:      {csv_path}")
    print(f"Markdown table: {md_path}")
    print(f"Learning curve: {path_curve}")
    print(f"Bars (100%):    {path_bars}")
    print(f"\nRuns saved at:  {out_dir}")
    print("=" * 60)


if __name__ == "__main__":
    main()
